select 'function' as kind,p.proname as name,has_function_privilege('anon',p.oid,'EXECUTE') as anon_allowed,has_function_privilege('authenticated',p.oid,'EXECUTE') as authenticated_allowed,has_function_privilege('service_role',p.oid,'EXECUTE') as service_role_allowed,p.prosecdef as security_definer from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('jra_manual_readiness_v1','jra_manual_claim_next_v1','jra_claim_prediction_jobs','jra_claimed_context') union all select 'table',c.relname,has_table_privilege('anon',c.oid,'SELECT'),has_table_privilege('authenticated',c.oid,'SELECT'),has_table_privilege('service_role',c.oid,'SELECT'),c.relrowsecurity from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('jra_html_evidence','jra_lab_runs','jra_lab_races');
